let loteDeDownloads = { total: 0, feitas: 0, ok: 0 };
const TAG_DOWNLOAD = 'baixar';
const posicaoNoLote = () => (loteDeDownloads.total > 1 ? ` · música ${Math.min(loteDeDownloads.feitas + 1, loteDeDownloads.total)} de ${loteDeDownloads.total}` : '');
