    const s = db.song(id);
    if (!s?.baixado || s.baixarPausado || !(precisaBaixar(s) || precisaMelhorar(s)) || baixando.has(id)) return;
    if (!(await podeBaixarSozinho())) { completarDepois(id); return; }
