  if (!s?.baixado) return;
  const yts = Object.keys(s.baixado.arquivos || {});
  db.updateSong(s.id, { baixado: null, rebaixar: undefined });
  await Promise.all(yts.filter((y) => !baixadoDe(y)).map((y) => apagarAudio(chaveBaixada(y)).catch(() => {})));
