      for (let ofs = 0; ofs < arquivo.size; ofs += PARTE) {
        await nativo.arquivoParte({ processo, inicio: ofs === 0, dados: await emBase64(arquivo.slice(ofs, ofs + PARTE)) });
        passo(1 + 6 * Math.min(1, (ofs + PARTE) / arquivo.size), 'Abrindo a música');
      }
