      s = db.song(id);
      if (!s) return true;
      // (a mesma foto em outro tamanho é a mesma: pelo nome do arquivo)
      const arquivo = (u) => /\/([^/]+?\.(?:jpe?g|png|webp|gif))(?:\/|$|\?)/i.exec(String(u || '').replace(/\/\d+px-[^/]+$/, ''))?.[1] || u;
      if (certa === null) completa = false;
