    $('.pl-karaoke-pct b', kEl).textContent = `${Math.round(nivelVoz * 100)}%`;
    kEl.classList.toggle('sem-voz', nivelVoz <= 0.02);
    kEl.classList.toggle('topo-branco', nivelVoz * 168 >= 168 - 18);
