    paraModoVideo() { if (comCapa) { comCapa = false; db.setPref('playerCapa', false); desenharCapa(); } },
    // a música tocando foi baixada (ou o download saiu), ou a internet caiu ou voltou: passa a tocar do aparelho ou do
