// ---- busca na internet: Cifra Club, Letras e vídeos do YouTube

// ---- a música completa: cifra (Cifra Club), letra (Letras) e vídeo (YouTube), procurados juntos

const tituloLimpo = (t) => String(t || '').replace(/\s*[([].*?[)\]]\s*/g, ' ').replace(/\s*[–—-]\s*(cifra|letra|ao vivo|live|clipe|oficial).*$/i, '').trim();
const mesmoNome = (a, b) => { const A = normalizar(a); const B = normalizar(b); return !!A && !!B && (A === B || ` ${A} `.includes(` ${B} `) || ` ${B} `.includes(` ${A} `)); };
// quem canta: o artista e os participantes do título ("Aba (part. Kemuel)", "feat. X", "e Y")
const artistasDe = (titulo, artista) => {
  const part = [...String(titulo || '').matchAll(/\((?:part\.?|feat\.?|ft\.?|participa[çc][ãa]o( de)?|com)\s+([^)]+)\)/gi)].map((m) => m[2]);
  // (a dupla fica junta: "Jorge & Mateus" não vira "Jorge" e "Mateus"; veja artistasDoNome)
  return [artista, ...part].flatMap((x) => artistasDoNome(x)).map((x) => x.trim()).filter(Boolean);
};
// o nome sem espaços nem pontuação: "Jung Kook" e "Jungkook", "AC/DC" e "ACDC" são o mesmo artista
const nomeCompacto = (x) => normalizar(x).replace(/[^a-z0-9]/g, '');
const parecidoNome = (a, b) => { const A = nomeCompacto(a); const B = nomeCompacto(b); return A.length >= 2 && B.length >= 2 && (A.includes(B) || B.includes(A)); };
// entre os resultados de uma busca, a mesma música: mesmo título e (quando se sabe) mesmo artista,
// contando os participantes. Sem o artista certo, aceita o mesmo título exato entre os primeiros resultados só se o
// artista for o mesmo escrito de outro jeito (antes aceitava qualquer artista: "Neverender", do Justice, vinha com a
// letra e a cifra da "Neverender" do Coheed and Cambria)
// o mesmo artista, escrito de outro jeito ("Jorge & Mateus" e "Jorge e Mateus", "AC/DC" e "ACDC"); um nome de uma
// palavra só não vale como parte de outro ("Jorge" não é "Jorge & Mateus" — antes era, e a cifra vinha do Jorge Ben)
// o artista aparece no texto (o título e o canal do vídeo), com "&" ou "e" ligando a dupla de qualquer jeito
const artistaNoTexto = (a, texto) => { const A = semLigacao(a); return Boolean(A) && (` ${semLigacao(texto)} `.includes(` ${A} `) || (A.length >= 5 && nomeCompacto(semLigacao(texto)).includes(nomeCompacto(A)))); };
const semLigacao = (x) => normalizar(x).replace(/\b(e|and)\b/g, ' ').replace(/\s+/g, ' ').trim();
function mesmoArtistaNome(a, b) {
  const A = semLigacao(a);
  const B = semLigacao(b);
  if (!A || !B) return false;
  if (A === B || nomeCompacto(A) === nomeCompacto(B)) return true;
  const [curto, longo] = A.length <= B.length ? [A, B] : [B, A];
  return curto.includes(' ') && ` ${longo} `.includes(` ${curto} `);
}
// A mesma música entre os resultados de uma busca (a cifra, a letra): o título igual — o título só parecido ("Beija-flor"
// dentro de "Voa Beija-flor") vale apenas quando não há o igual — e do mesmo artista (a dupla não é separada)
function mesmaMusica(lista, titulo, artista, artistaIncerto = false) {
  const t = tituloLimpo(titulo);
  const iguais = lista.filter((r) => normalizar(tituloLimpo(r.titulo)) === normalizar(t));
  const doTitulo = iguais.length ? iguais : lista.filter((r) => mesmoNome(tituloLimpo(r.titulo), t));
  const quem = artistasDe(titulo, artista);
  const deQuem = (r) => artistasDe(r.titulo, r.artista).some((a) => quem.some((b) => mesmoArtistaNome(a, b)));
  const certo = (iguais.length ? iguais : []).find((r) => !quem.length || deQuem(r)) || doTitulo.find((r) => !quem.length || deQuem(r));
  if (certo) return certo;
  if (artistaIncerto || !quem.length) return doTitulo[0] || null;
  return lista.slice(0, 3).find((r) => normalizar(tituloLimpo(r.titulo)) === normalizar(t)
    && artistasDe(r.titulo, r.artista).some((a) => quem.some((b) => parecidoNome(a, b) && mesmoArtistaNome(a, b)))) || null;
}

// A cifra certa da música no Cifra Club (lib/cifras.js): as achadas com o título dela — primeiro a do artista dela,
// depois as do mesmo título de outros artistas — são trazidas uma por vez e conferidas pela letra (a do Letras ou a do
// LRCLIB, ou a que a música já tem). A primeira cuja letra é a da música vale; nenhuma sendo, nenhuma (antes vinha a
// primeira achada, que às vezes era de outra música). Sem a letra da música para comparar, só a do artista dela
// letra: o texto da letra, ou uma promessa dele (espera até 6 s); cifraUrl: a escolhida na busca, que vem primeiro
// A cifra salva conferida de novo (a revisão das músicas salvas): pela letra sincronizada (a do LRCLIB, que é a da
// gravação), e, nas baixadas, pelo som. A cifra de outra música é trocada pela certa, se for achada; a escrita ou mudada
// pela pessoa fica. false: sem internet, para tentar de novo depois
async function conferirCifraSalva(id) {
  let s = db.song(id);
  if (!s || s.cifraEditada || !temCifra(s.content || '') || !ehCifraClub(s.source || '')) return true;
  if (!navigator.onLine) return false;
  const linhas = s.sincronia?.fonte === 'lrclib' && Array.isArray(s.sincronia.linhas) ? s.sincronia.linhas.join('\n') : '';
  const p = linhas ? parecencaDaLetra(s.content, linhas) : null;
  if (p !== null && p < 0.3) {
    const c = await cifraCertaNoCifraClub(s.title, s.artist, { letra: linhas }).catch(() => null);
    s = db.song(id);
    if (s && c && c.url !== s.source && temCifra(c.chordpro) && !s.cifraEditada) {
      let content = c.chordpro;
      const meta = renderSong(s.content).meta;
      for (const k of ['youtube', 'x_canvas', 'x_parte', 'composer', 'cover']) if (meta[k]) content = definirMeta(content, k, meta[k]);
      db.updateSong(id, { content, source: c.url, capo: capoDaCifra(content) || 0, ...(s.tomManual ? {} : { transpose: 0, tomGravacao: undefined }) });
      s = db.song(id);
    }
  }
  // (nas baixadas, o som: os acordes conferidos com a gravação de novo, agora também trocando a cifra que não casa)
  if (s?.baixado && !s.tomManual) {
    if (s.tomGravacao && !(s.tomGravacao.casamento < 0.4)) return true;
    db.updateSong(id, { tomGravacao: undefined });
    await noMaximo(ajustarTomDaGravacao(db.song(id)), 90000, false).catch(() => {});
  }
  return true;
}

// (procura pelo título com o artista, com cada participante e só pelo título)
async function cifraCertaNoCifraClub(titulo, artista = '', { artistaIncerto = false, letra = '', cifraUrl = '' } = {}) {
  const t = tituloLimpo(titulo);
  const consultas = [...new Set([`${t} ${artista}`.trim(), ...artistasDe(titulo, '').map((a) => `${t} ${a}`), t])];
  const achadas = new Map();
  let doArtista = null;
  for (const q of consultas) {
    const lista = await buscarCifraClub(q).catch(() => []);
    lista.forEach((r) => { if (!achadas.has(r.url)) achadas.set(r.url, r); });
    doArtista ||= mesmaMusica(lista, titulo, artista, artistaIncerto);
    if (doArtista) break;
  }
  const igual = (r) => normalizar(tituloLimpo(r.titulo)) === normalizar(t);
  const outras = [...achadas.values()].filter((r) => r.url !== doArtista?.url && r.url !== cifraUrl && igual(r));
  const candidatas = [...(cifraUrl ? [{ url: cifraUrl }] : []), ...(doArtista && doArtista.url !== cifraUrl ? [doArtista] : []), ...outras].slice(0, 4);
  if (!candidatas.length) return null;
  let textoDaLetra = null;
  const letraDaMusica = async () => {
    if (textoDaLetra === null) {
      const l = typeof letra === 'string' ? letra : await noMaximo(Promise.resolve(letra), 6000, null);
      textoDaLetra = typeof l === 'string' ? l : l?.letra || '';
    }
    return textoDaLetra;
  };
  const trazidas = [];
  for (const [i, c] of candidatas.entries()) {
    // (sem a letra para conferir, as de outros artistas não entram: podiam ser de outra música)
    if (i > 0 && !(await letraDaMusica()) && c !== doArtista) break;
    const pg = await getCifraClub(c.url).catch(() => getCifraClub(c.url)).catch(() => null);
    if (!pg) continue;
    trazidas.push({ ...pg, url: c.url });
    const p = parecencaDaLetra(pg.chordpro, await letraDaMusica());
    if (p === null || p >= 0.5) break;
  }
  return escolherCifra(trazidas, await letraDaMusica());
}


// "Padre Marcelo Rossi - Deus Está Aqui (Noites Traiçoeiras) ft. Belo" -> artista e título
// ("Ninguém Te Ama Como Eu | Frei Gilson": com a barra, o título vem antes)
const tituloCruDoVideo = (t) => String(t || '').replace(/\s*[([{【][^)\]}】]*[)\]}】]/g, ' ').replace(/\s+/g, ' ').trim();
function nomesDoVideo(v) {
  const semFeat = (x) => x.replace(/\s+(ft\.?|feat\.?|part\.?|com)\s.+$/i, '').trim();
  const cru = tituloCruDoVideo(v.titulo);
  return nomesSeparadosDoTitulo(cru, v.canal || '', semFeat) || (() => {
    const limpo = semFeat(tituloDoVideo(v.titulo));
    const [artista, titulo] = / [-–—] /.test(limpo) ? [limpo.split(/ [-–—] /)[0].trim(), limpo.split(/ [-–—] /).slice(1).join(' - ').trim()] : [v.canal || '', limpo];
    return { titulo: tituloLimpo(titulo) || titulo, artista };
  })();
}
// "Música | Artista" e "Música // Evento" (como os vídeos de música católica: "Odres Novos // Luau da Imaculada II", no
// canal do ministério): a parte que é o canal (ou o artista que se sabe) é o artista; o título é a primeira das outras.
// Com " | " e duas partes, sem o canal em nenhuma, a segunda é o artista; com " // ", o artista é o canal (a outra parte
// é o evento, o álbum). null se o título não tem esses separadores (ou tem o traço "Artista - Música")
function nomesSeparadosDoTitulo(cru, artistaSabido = '', semFeat = (x) => x) {
  const SEP = / (?:\||\/\/) /;
  if (!SEP.test(cru) || / [-–—] /.test(cru)) return null;
  const partes = cru.split(SEP).map((x) => x.trim()).filter(Boolean);
  if (partes.length < 2) return null;
  const iArt = artistaSabido ? partes.findIndex((x) => mesmoNome(x, artistaSabido) || parecidoNome(x, artistaSabido)) : -1;
  let titulo;
  let artista;
  if (iArt >= 0) { artista = partes[iArt]; titulo = partes.find((_, j) => j !== iArt); }
  else if (/ \/\/ /.test(cru)) { titulo = partes[0]; artista = artistaSabido; }
  else { [titulo, artista] = partes; }
  return { titulo: tituloLimpo(semFeat(titulo)) || titulo, artista: artista || artistaSabido };
}

// Vídeo escolhido na busca: qual música é? Procura no Cifra Club e no Letras pelo título do vídeo inteiro e fica com
// a música cujo título está no título do vídeo (de preferência do artista que aparece no título ou no canal).
// Assim o vídeo vem com a cifra e a letra certas; sem achar, segue pelo nome tirado do título do vídeo.
// conhecido: o título e o artista que a busca já sabia (o resultado "Neverender · Justice"). Com o artista sabido (por
// ela ou escrito no título do vídeo, "Justice - Neverender"), a música de outro artista com o mesmo título não serve
async function musicaDoVideo(v, conhecido = {}) {
  const cru = tituloCruDoVideo(v.titulo);
  const noVideo = ` ${normalizar(cru)} `;
  const artistaConhecido = String(conhecido.artista || '').trim();
  const quem = `${quemNoVideo(v)}${normalizar(artistaConhecido)} `;
  const lista = await buscarMusicas(cru.replace(/\s(?:[|–—-]|\/\/)\s/g, ' ')).catch(() => []);
  const tit = (r) => normalizar(tituloLimpo(r.titulo));
  const cabe = lista.filter((r) => tit(r).length >= 3 && noVideo.includes(` ${tit(r)} `));
  const doArtista = cabe.filter((r) => r.artista && artistasDe('', r.artista).some((a) => artistaNoTexto(a, quem)));
  const maior = (l) => [...l].sort((a, b) => tit(b).length - tit(a).length)[0];
  // "Justice - Neverender": o que vem antes do traço é o artista, a não ser que seja o próprio título ("Música - Ao Vivo")
  const esquerda = / [-–—] /.test(cru) ? normalizar(cru.split(/ [-–—] /)[0]) : '';
  const artistaNoTitulo = esquerda && !cabe.some((r) => tit(r) === esquerda) ? esquerda : '';
  const artistaSabido = artistaConhecido || artistaNoTitulo;
  // (o canal do próprio artista — "Ministério Gerados pela Imaculada" — também diz de quem é a música: a de mesmo título
  // de outro artista não serve. Antes, "Odres Novos" vinha com a cifra e a letra da "Odres Novos" de outro ministério)
  const canalDoArtista = Boolean(v.canal) && !canalDeGravadora(v.canal);
  const r = maior(doArtista) || (artistaSabido || canalDoArtista ? null : maior(cabe));
  if (r) return { titulo: r.titulo, artista: r.artista, cifra: r.cifra || '', letra: r.letra || null, video: v };
  if (artistaConhecido) return { titulo: conhecido.titulo || nomesDoVideo(v).titulo, artista: artistaConhecido, video: v };
  // o artista escrito no título do vídeo (ou o canal dele) é certo: a cifra e a letra têm de ser dele
  if (artistaNoTitulo || canalDoArtista) return { ...nomesDoVideo(v), video: v };
  return { ...nomesDoVideo(v), video: v, artistaIncerto: true };
}
// o canal que não é do artista (a gravadora, o selo, o canal automático do YouTube, um canal de vários artistas): o
// nome dele não diz de quem é a música
const canalDeGravadora = (c) => /\b(records?|recordings|music|musica|música|label|labels|vevo|topic|entertainment|entretenimento|produ[cç](ões|oes|ão|ao)|gravadora|sony|warner|universal|som livre|emi|hybe|smtown|jyp|yg|tv|radio|rádio|lyrics?|letras?|karaok[eê]|cifras?)\b|\s-\s/i.test(String(c || ''));

// Traz tudo de uma vez: a cifra do Cifra Club (que já tem a letra); sem cifra, a letra do Letras; e o
// vídeo do YouTube. Devolve { content, source, video } (video é a busca, que pode ainda estar andando).
// As buscas de vídeos ficam guardadas por 10 minutos: a mesma busca (a do áudio oficial, a do clipe) feita ao preparar
// a música da busca e de novo ao abrir ela não espera a internet duas vezes
const buscasYoutube = new Map();
function buscarYoutube(termo, opcoes = {}) {
  const k = `${opcoes.filtro || 'videos'}|${String(termo || '').trim().toLowerCase()}`;
  const ja = buscasYoutube.get(k);
  if (ja && Date.now() - ja.em < 600e3) return ja.p;
  const p = buscarYoutubeNaWeb(termo, opcoes);
  buscasYoutube.set(k, { p, em: Date.now() });
  p.catch(() => buscasYoutube.delete(k));
  if (buscasYoutube.size > 300) buscasYoutube.delete(buscasYoutube.keys().next().value);
  return p;
}
// A música da busca preparada antes do toque (como no Spotify, que abre na hora): a cifra, a letra e o vídeo
// (trazerMusica), a letra sincronizada, a duração do vídeo, o áudio oficial e a capa. As primeiras da lista começam
// assim que ela aparece; qualquer outra, no instante em que o dedo encosta nela. Ao abrir, quase tudo já está pronto
const trazendo = new Map();
const chaveDaTrazida = (d) => [d.titulo, d.artista, d.cifra, d.letra?.url, d.video?.id].map((x) => String(x || '')).join('|');
function trazerMusicaJa(dados) {
  const k = chaveDaTrazida(dados);
  const ja = trazendo.get(k);
  if (ja && Date.now() - ja.em < 600e3) return ja.p;
  const p = trazerMusica(dados);
  trazendo.set(k, { p, em: Date.now() });
  // (só fica guardada a que trouxe a cifra ou a letra: a falha de um instante é pedida de novo)
  p.then((r) => { if (!r?.source) trazendo.delete(k); }, () => trazendo.delete(k));
  if (trazendo.size > 60) trazendo.delete(trazendo.keys().next().value);
  return p;
}
const preparadas = new Set();
// (completo: a música que o dedo tocou, prestes a abrir, prepara tudo. As três primeiras da lista, preparadas sozinhas,
// só trazem a cifra, a letra e o vídeo: a procura do áudio oficial faz 5 buscas no YouTube por música, e as três juntas
// ocupavam a internet do celular bem na hora em que a pessoa escolhia e abria a música)
function prepararDaBusca(dados, { completo = true } = {}) {
  if (!dados?.titulo || !navigator.onLine) return;
  // (o vídeo solto da busca descobre a música ao abrir; e a que já está na biblioteca abre direto)
  if (dados.video && !dados.cifra && !dados.letra) return;
  const k = chaveDaTrazida(dados) + (completo ? '|tudo' : '');
  if (preparadas.has(k)) return;
  preparadas.add(k);
  setTimeout(() => preparadas.delete(k), 600e3);
  if (musicaSalva({ titulo: dados.titulo, artista: dados.artista, cifra: dados.cifra || '', letra: dados.letra?.url || '' })) return;
  if (dados.artista && !dados.artistaIncerto) void letraSincronizadaJa(dados.titulo, dados.artista).catch(() => null);
  void (async () => {
    const r = await trazerMusicaJa(dados);
    const m = renderSong(r.content).meta;
    const titulo = m.title || dados.titulo;
    const artista = m.artist || m.subtitle || dados.artista || '';
    if (titulo && artista) {
      void letraSincronizadaJa(titulo, artista).catch(() => null);
      void capaOficial(titulo, artista).catch(() => '');
    }
    if (!completo) return;
    const vs = await r.video.catch(() => []);
    const youtube = youtubeId(m.youtube) || vs?.[0]?.id || '';
    if (!youtube) return;
    void duracaoDaMusica({ youtube }).catch(() => 0);
    void videoParado(youtube); // (o vídeo é clipe ou só a capa: já sabido ao abrir)
    // (as mesmas buscas do áudio oficial que a música faz ao abrir: ficam guardadas e ela não espera de novo)
    if (titulo) void procurarAudio({ title: titulo, artist: artista, youtube }, 0).catch(() => null);
  })().catch(() => {});
}

async function trazerMusica({ titulo, artista = '', cifra = '', letra = null, video = null, artistaIncerto = false }) {
  const termo = `${tituloLimpo(titulo)} ${artista}`.trim();
  // a cifra certa: conferida pela letra da música (a que vem do Letras/LRCLIB, logo abaixo)
  const pCifra = (async () => {
    await null; // (a letra, logo abaixo, já está sendo procurada quando a cifra precisar dela)
    return cifraCertaNoCifraClub(titulo, artista, { artistaIncerto, cifraUrl: cifra, letra: pLetra });
  })().catch(() => null);
  // o vídeo é procurado junto com a cifra (pelo título e o artista da busca); só com o link da cifra, sem o nome,
  // espera a cifra para procurar pelo nome que vem nela
  const pBusca = (video ? Promise.resolve([video])
    : cifra && !tituloLimpo(titulo) ? pCifra.then((c) => buscarYoutube(c ? `${c.titulo} ${c.artista || ''}` : termo).then((vs) => (c ? videosDaMusica(vs, c.titulo, c.artista) : vs)))
      : buscarYoutube(termo).then((vs) => videosDaMusica(vs, titulo, artista))).catch(() => []);
  // a busca de vídeos não respondeu ou não achou: o vídeo que a página da letra (Letras) mostra
  const pVideo = pBusca.then(async (vs) => {
    if (vs.length) return vs;
    const l = await pLetra;
    return l?.youtube ? [{ id: youtubeId(l.youtube), url: l.youtube }] : [];
  });
  const pLetra = (async () => {
    // no Letras: pelo título com o artista e, se não achar, só pelo título
    let item = letra || mesmaMusica(await buscarLetras(termo).catch(() => []), titulo, artista, artistaIncerto);
    if (!item && artista) item = mesmaMusica(await buscarLetras(tituloLimpo(titulo)).catch(() => []), titulo, artista, artistaIncerto);
    if (item) { const l = await trazerLetra(item); return { ...l, url: l.url || item.url }; }
    // fora do Letras: LRCLIB e Vagalume
    return await letraReserva(tituloLimpo(titulo), artistaIncerto ? '' : artista);
  })().catch(() => null);
  const c = await pCifra;
  let content;
  let source;
  if (c) {
    content = c.chordpro;
    source = c.url;
    // o Letras costuma ter o compositor: entra nos créditos se chegar logo
    const l = await Promise.race([pLetra, new Promise((r) => setTimeout(() => r(null), 1500))]);
    if (l?.compositor && !renderSong(content).meta.composer) content = definirMeta(content, 'composer', l.compositor);
    if (l?.youtube && !youtubeId(renderSong(content).meta.youtube)) content = definirMeta(content, 'youtube', l.youtube);
  } else {
    const l = await pLetra;
    if (l) {
      content = letraParaChordPro({ titulo: l.titulo, artista: l.artista, compositor: l.compositor, letra: l.letra, fonte: l.url });
      if (l.youtube) content = definirMeta(content, 'youtube', l.youtube); // o vídeo que o Letras mostra com a letra
      source = l.url;
    } else {
      content = `{title: ${titulo}}\n${artista ? `{artist: ${artista}}\n` : ''}\n{comment: Não achei a letra nem a cifra: toque em Editar → Trazer da internet}\n`;
      source = '';
    }
  }
  if (video) content = definirMeta(content, 'youtube', video.url); // o vídeo escolhido vale mais que o da página da cifra
  return { content, source, video: pVideo };
}

// abre a música da busca já com cifra, letra e vídeo
// (tela: abre sempre a tela da música, tocando — o Lumen leva a pessoa até a música que ela pediu)
// Ao tocar numa música que ainda está sendo preparada: em vez do círculo girando no lugar dos botões da linha, a tela
// da música abre na hora, com a cor, a capa, o nome e o contorno da letra; quando tudo chega (a cifra, o vídeo, a letra
// sincronizada), a tela de verdade entra no lugar. A seta de voltar (ou o voltar do celular) desiste da música
let abrindoDaBusca = 0;
function telaChegando(dados) {
  const titulo = dados.titulo || 'Música';
  const img = dados.capa || dados.cover || dados.video?.capa || capaConhecida(titulo, dados.artista || '') || '';
  const el = document.createElement('div');
  el.className = 'chegando';
  el.style.setProperty('--cor', corDaMusica(titulo));
  el.innerHTML = `<div class="ch-topo"><button class="icon-btn" data-fechar aria-label="Voltar">${icon('down', 24)}</button>
      <span class="grow"><b>${esc(titulo)}</b><small>${esc(dados.artista || '')}</small></span><span class="ch-vago"></span></div>
    <div class="ch-capa">${img ? `<img src="${esc(img)}" alt="">` : icon('music', 56)}</div>
    <div class="ch-letra" aria-hidden="true">${[78, 62, 84, 55, 70, 88, 60, 74].map((w) => `<i class="esq" style="width:${w}%"></i>`).join('')}</div>`;
  el.setAttribute('role', 'status');
  el.setAttribute('aria-label', `Abrindo ${titulo}`);
  document.body.append(el);
  requestAnimationFrame(() => el.classList.add('aberta'));
  const meu = ++abrindoDaBusca;
  let fechada = false;
  const fechar = (desistiu = false) => {
    if (fechada) return;
    fechada = true;
    if (desistiu && abrindoDaBusca === meu) abrindoDaBusca++;
    removeEventListener('hashchange', aoNavegar);
    el.classList.remove('aberta');
    setTimeout(() => el.remove(), 250);
  };
  // (outra tela aberta no meio: desiste; a própria música chegando fecha a tela logo depois de desenhada)
  const aoNavegar = () => { if (location.hash === '#/musica/previa' && abrindoDaBusca === meu) setTimeout(() => fechar(), 120); else fechar(true); };
  addEventListener('hashchange', aoNavegar);
  el.querySelector('[data-fechar]').onclick = () => fechar(true);
  const aoTeclar = (e) => { if (e.key === 'Escape') { removeEventListener('keydown', aoTeclar); fechar(true); } };
  addEventListener('keydown', aoTeclar);
  return { meu, fechar: (desistiu) => { removeEventListener('keydown', aoTeclar); fechar(desistiu); } };
}

async function abrirMusica(dados, back, el, { tela = false } = {}) {
  // já está na biblioteca: abre a música salva (com o botão marcado), sem trazer de novo
  const ja = (!dados.video || dados.cifra || dados.letra) && musicaSalva({ titulo: dados.titulo, artista: dados.artista, cifra: dados.cifra || '', letra: dados.letra?.url || '' });
  if (ja) { if (tela) abrirTocando(ja.id); else irParaMusica(ja.id); return; }
  // (com o player aberto: a música é preparada e só passa a tocar nele, sem abrir a tela)
  const noPlayer = !tela && playerAberto();
  abrirNoTocando = true;
  // (com o player aberto, a música vai para ele: a linha só pulsa de leve enquanto prepara; senão, a tela dela abre já)
  const chegando = noPlayer ? null : telaChegando(dados);
  if (noPlayer && el) el.classList.add('preparando');
  else if (noPlayer) toast('Trazendo a música…');
  try {
    // vídeo da busca: primeiro descobre qual música é (para vir com a cifra e a letra dela)
    // (enquanto prepara, a linha tocada mostra só o círculo girando, como no Spotify; o que está sendo feito fica para o
    // leitor de tela, sem textos aparecendo e sumindo embaixo do nome)
    const aoPreparar = (txt) => { if (el?.isConnected) { el.setAttribute('aria-busy', 'true'); el.setAttribute('aria-description', txt); } };
    aoPreparar('Trazendo a cifra e a letra…');
    // (a letra sincronizada já começa a ser procurada agora, junto com a cifra e o vídeo)
    if (dados.titulo && dados.artista && !dados.artistaIncerto) void letraSincronizadaJa(dados.titulo, dados.artista).catch(() => null);
    try {
      const r = dados.video && !dados.cifra && !dados.letra ? await trazerMusica(await musicaDoVideo(dados.video, dados)) : await trazerMusicaJa(dados);
      if (chegando && chegando.meu !== abrindoDaBusca) return;
      await abrirPrevia(r.content, r.source, back, r.video, aoPreparar, { noPlayer, vez: chegando?.meu });
    } finally { el?.removeAttribute('aria-busy'); el?.removeAttribute('aria-description'); }
  } catch (e) {
    abrirNoTocando = false;
    toast('Não consegui trazer: ' + e.message);
  } finally {
    el?.classList.remove('preparando');
    // (abriu: a tela de verdade já está por baixo; não abriu ou desistiu: fecha e volta para onde estava)
    if (chegando) setTimeout(() => chegando.fechar(), location.hash === '#/musica/previa' ? 150 : 0);
  }
}

// vídeo tocado direto da busca: abre como música, com a cifra e a letra
async function abrirVideoComoMusica(v) {
  await abrirMusica({ ...nomesDoVideo(v), video: v, artistaIncerto: true }, location.hash);
  // o player passa a ser desta música (a prévia, ou a salva, se já estava na biblioteca): o salvar dele funciona
  const id = /^#\/musica\/([^/?]+)/.exec(location.hash)?.[1];
  if (id && player.atual?.youtube === v.id) player.atualizar({ songId: id, href: '#/musica/' + id, abrir: null });
}

// leva para a Buscar já procurando cifras desta música
function buscarCifraNoApp(song) {
  sessionStorage.setItem('busca', [song.title.replace(/\s*[–—-]\s*cifra.*$/i, ''), song.artist].filter(Boolean).join(' '));
  sessionStorage.setItem('buscaFiltro', 'musicas');
  location.hash = '#/buscar';
}

// Abre a música da busca já com o vídeo do YouTube (procura por até 3 s antes de abrir, para a página
// ser desenhada uma vez só); se a busca demorar mais, ela continua com a página aberta
// vídeo de referência da música. Para os cantos do acervo litúrgico e do Hinário da CNBB (nomes curtos e comuns,
// como "Santo I" ou "Aleluia"), a busca leva "canto litúrgico" e o vídeo só vale se o título dele tiver as palavras
// do canto: sem isso, melhor ficar sem vídeo do que com um errado
const PALAVRAS_VAZIAS = new Set(['que', 'nos', 'vos', 'dos', 'das', 'com', 'para', 'por', 'uma', 'ano', 'missa', 'canto', 'antifona', 'opcao']);
const palavrasDoTitulo = (t) => normalizar(String(t || '').replace(/\([^)]*\)/g, ' ')).split(' ').filter((p) => p.length >= 3 && !PALAVRAS_VAZIAS.has(p) && !/^\d+$/.test(p));
function videoCombina(tituloVideo, titulo) {
  const ps = palavrasDoTitulo(titulo).slice(0, 6);
  if (!ps.length) return false;
  const v = ` ${normalizar(tituloVideo)} `;
  return ps.filter((p) => v.includes(p)).length / ps.length >= 0.6;
}
async function videoDaMusica(titulo, artista, source) {
  if (!/^(acervo|hinario):/.test(source || '')) return videosDaMusica(await buscarYoutube([titulo, artista].filter(Boolean).join(' ')), titulo, artista)[0] || null;
  const autor = String(artista || '').replace(/hin[áa]rio lit[úu]rgico cnbb|\b(svd|ofm|ofmcap|sj|pe\.|padre|frei|fr\.|ir\.|d\.r\.)/gi, ' ').replace(/[,.]/g, ' ').trim();
  const extra = String(source).startsWith('hinario:') ? 'hinário litúrgico CNBB' : 'canto litúrgico';
  const vs = [...await buscarYoutube(`${titulo} ${autor} ${extra}`).catch(() => []), ...(autor ? await buscarYoutube(`${titulo} ${extra}`).catch(() => []) : [])];
  return vs.find((v) => videoCombina(v.titulo, titulo)) || null;
}

async function abrirPrevia(content, source, back, videoJa = null, aoPreparar = null, { noPlayer = false, vez = 0 } = {}) {
  const novo = { id: 'previa', content, source, transpose: 0, capo: capoDaCifra(content), back }; // capo da cifra (Cifra Club)
  let m = renderSong(novo.content).meta;
  if (!youtubeId(m.youtube) && !String(source || '').startsWith('cnbb:')) {
    // Aguarda o videoclipe da busca; se ela não encontrou, tenta pelo título e artista.
    const busca = (videoJa
      ? videoJa.then((vs) => vs?.[0] || videoDaMusica(m.title, m.artist, source))
      : videoDaMusica(m.title, m.artist, source)).catch(() => null);
    // (espera o vídeo só um pouco: a busca do YouTube às vezes leva muitos segundos, e a música esperava por ela antes
    // de abrir. Passando disso, abre sem ele, e o vídeo entra sozinho quando chegar, com o áudio e a letra dele)
    const ATRASOU = {};
    const v = await noMaximo(busca, 4000, ATRASOU);
    novo.videoProcurado = true;
    if (v === ATRASOU) {
      void busca.then((tarde) => {
        if (preview !== novo || novo.youtube) return;
        if (!tarde?.url) { novo.semVideo = true; return; }
        novo.content = definirMeta(novo.content, 'youtube', tarde.url);
        novo.youtube = youtubeId(tarde.url) || '';
        novo.semVideo = false;
        void prepararMusicaAoAbrir(novo).catch(() => null);
        if (location.hash === '#/musica/previa') route();
      });
    } else if (v?.url) novo.content = definirMeta(novo.content, 'youtube', v.url);
    else novo.semVideo = true;
  }

  // A prévia também precisa ter os metadados explícitos: sem title/artist/youtube,
  // a descoberta da faixa de áudio e a consulta ao LRCLIB não conseguem identificar a música.
  m = renderSong(novo.content).meta;
  Object.assign(novo, {
    title: m.title || 'Canto',
    artist: m.artist || m.subtitle || '',
    youtube: youtubeId(m.youtube) || '',
    cover: m.cover || '',
  });

  // o vídeo que é só a capa parada (ou só o áudio, ou o de um canal que não é oficial) não é clipe: no lugar dele, o clipe
  // oficial; sem clipe oficial, a música abre só como música (o vídeo continua sendo o som dela). Venha o vídeo da
  // busca ou da página da cifra. Com limite de tempo: passando, abre como está
  if (novo.youtube && !String(source || '').startsWith('cnbb:')) {
    if (!(await noMaximo(ehClipe({ id: novo.youtube }, novo.artist), 2000, true))) {
      const clipe = await noMaximo(procurarClipe(novo.title, novo.artist, novo.youtube), 3000, null);
      if (clipe) {
        novo.content = definirMeta(novo.content, 'youtube', `https://www.youtube.com/watch?v=${clipe.id}`);
        novo.youtube = clipe.id;
        novo.semClipe = false;
      } else novo.semClipe = true;
    } else novo.semClipe = false;
  }

  const jaNaPrevia = location.hash === '#/musica/previa';
  preview = novo;

  // A capa original é buscada em paralelo com áudio e LRCLIB. Ela não depende do resultado dessas etapas.
  const buscaCapaDaPrevia = novo.title && novo.artist
    ? capaOficial(novo.title, novo.artist).catch(() => '')
    : Promise.resolve('');
  const buscaFotoDaPrevia = novo.title && novo.artist
    ? fotoDaPessoa(novo.artist, { liturgia: ehDaLiturgia(novo), slug: /cifraclub\.com\.br\/([^/?#]+)/.exec(source || '')?.[1] || '' }).catch(() => '')
    : Promise.resolve('');
  void buscaFotoDaPrevia.then((url) => {
    if (!url || preview !== novo) return;
    novo.fotoArtista = url;
    if (db.songBySource(novo.source)) db.updateSong(db.songBySource(novo.source).id, { fotoArtista: url });
  });
  const aplicarCapaDaPrevia = (url) => {
    if (!url || preview !== novo || !capaTrocavel(novo.cover)) return;
    novo.cover = url;
    novo.content = definirMeta(novo.content, 'cover', url);
    if (player.atual?.songId === 'previa') player.atualizar({ capa: url });
    // Se a busca terminar depois da navegação, atualiza a capa que já está na tela sem reiniciar o player.
    if (location.hash === '#/musica/previa') {
      const box = $('#view .song-hero > .cover');
      if (box) {
        box.classList.remove('gen');
        box.innerHTML = `<img src="${esc(url)}" alt="${esc(novo.title)}" loading="eager">`;
      }
    }
  };
  void buscaCapaDaPrevia.then(aplicarCapaDaPrevia);

  // a capa que já se conhece desta música entra de primeira (sem a do vídeo antes)
  if (capaTrocavel(novo.cover)) aplicarCapaDaPrevia(capaConhecida(novo.title, novo.artist));

  // A sincronização LRCLIB é complementar: uma falha ou demora não deve impedir a abertura da música. Espera um
  // tempo razoável (a maioria responde em 1–3 s); passou disso, a música abre e a letra sincronizada entra sozinha
  // quando chegar (o evento songbook:sincronia). Sem sincronia, a música abre mesmo assim e mostra que não tem.
  novo.sincronizando = true;
  const preparo = prepararMusicaAoAbrir(novo).catch(() => 'erro').then((r) => {
    if (preview === novo) {
      novo.sincronizando = false;
      novo.semSincronia = r !== 'ok';
      window.dispatchEvent(new CustomEvent('songbook:estado-sincronia', { detail: { song: 'previa' } }));
    }
    return r;
  });
  // Enquanto carrega, também as duas versões (o áudio oficial e o clipe) e onde cada trecho cantado está em cada uma
  // (o casamento pelo som), para a troca entre música e vídeo já ir ao ponto certo desde o primeiro toque. Com limite:
  // passando dele, a música abre e o resto termina em segundo plano
  // A música só abre com tudo pronto: a versão de música (o áudio oficial), o clipe e a letra sincronizada. Espera até
  // achar (com limite de 15 s, para nunca ficar presa); o que não chegar a tempo entra sozinho logo depois
  const versoesProntas = novo.youtube ? descobrirVersoes(novo).catch(() => null) : Promise.resolve(null);
  aoPreparar?.('Procurando a música, o clipe e a letra sincronizada…');
  void versoesProntas.then(() => { if (preview === novo && !novo.sincronia) aoPreparar?.('Sincronizando a letra…'); });
  // (com limite curto: a pessoa quer a música na hora. A letra sincronizada, o áudio oficial e o clipe que chegarem
  // depois entram sozinhos, sem precisar abrir de novo: songbook:sincronia e o casamento das versões em segundo plano.
  // Antes eram até 25 s esperando a letra e 15 s o áudio, e a música da busca demorava muito para abrir)
  await Promise.all([noMaximo(preparo, 3500, 'demorou'), noMaximo(versoesProntas, 3500, null), noMaximo(buscaCapaDaPrevia, 1500, '').then(aplicarCapaDaPrevia)]);
  if (preview !== novo) return;
  // (a pessoa desistiu enquanto a música chegava: voltou ou abriu outra tela)
  if (vez && vez !== abrindoDaBusca) return;
  // com o player aberto: ela toca nele, e a tela abre tocando no player (a música sem vídeo abre a tela, para escolher um)
  if (noPlayer && novo.youtube && !jaNaPrevia && playerAberto()) {
    abrirNoTocando = false;
    player.tocar({ ...itemDoPlayer(novo), href: '#/musica/previa' });
    return;
  }
  if (jaNaPrevia) route(); else location.hash = '#/musica/previa';
}

// Letra: do Letras (lida na hora) ou do LRCLIB (já vem com a letra); se a página do Letras não abrir, procura
// a mesma música no LRCLIB e no Vagalume (antes a reserva buscava no próprio Letras de novo e nunca achava)
async function trazerLetra(item) {
  if (item.letra) return item;
  try { return { ...item, ...(await getLetra(item.url)) }; } catch {
    const alt = await letraReserva(tituloLimpo(item.titulo), item.artista).catch(() => null)
      || await letraReserva(tituloLimpo(item.titulo)).catch(() => null);
    if (alt) return { ...alt, url: alt.url || item.url };
    throw new Error('O Letras não respondeu agora');
  }
}

// texto colado (cifra de qualquer site, letra pura ou ChordPro) -> ChordPro com título e autor
function textoParaChordPro(texto, { titulo = '', artista = '', url = '' } = {}) {
  const t = semInvisiveis(texto).replace(/\r\n?/g, '\n').trim();
  let corpo;
  if (looksLikeChordPro(t) && !/^\s*\[[^\]]*[a-z]{3,}[^\]]*\]\s*$/m.test(t)) corpo = t;
  else if (t.split('\n').some(isChordOnlyLine)) corpo = cifraTextoParaChordPro(t);
  else corpo = letraParaChordPro({ letra: t }).replace(/^\{title:[^}]*\}\n+/, '');
  const cab = [];
  if (!/\{\s*(title|t)\s*:/i.test(corpo)) cab.push(`{title: ${titulo || 'Sem título'}}`);
  if (artista && !/\{\s*(artist|a)\s*:/i.test(corpo)) cab.push(`{artist: ${artista}}`);
  if (url && !/\{\s*source\s*:/i.test(corpo)) cab.push(`{source: ${url}}`);
  return (cab.length ? cab.join('\n') + '\n\n' : '') + corpo;
}

// Trazer cifra/letra de qualquer site: link do Cifra Club, ou colar o texto copiado
function importarDaInternet({ titulo = '', artista = '', url = '', back = location.hash, aviso = false, paraEditor = null } = {}) {
  const busca = [titulo, artista].filter(Boolean).join(' ');
  return openDialog(`
    <h3>${paraEditor ? 'Trazer cifra ou letra' : 'Importar da internet'}</h3>
    ${aviso ? `<div class="aviso" style="margin:0">${icon('info', 18)}<span>O Cifra Club não deixou abrir a cifra direto daqui. Abra o site, copie a cifra (Ctrl+C ou "Copiar") e cole abaixo — o app organiza acordes, partes e refrão.</span></div>` : ''}
    <div class="row" style="gap:8px">
      ${url ? `<a class="btn small" href="${esc(url)}" target="_blank" rel="noopener">${icon('external', 15)} Abrir no ${esc(host(url))}</a>` : ''}
      ${busca ? `<a class="btn small" href="https://www.google.com/search?q=${encodeURIComponent('cifra ' + busca)}" target="_blank" rel="noopener">${icon('search', 15)} Procurar na internet</a>` : ''}
      <button class="btn small" data-colar>${icon('upload', 15)} Colar copiado</button>
    </div>
    ${url ? '' : `<label class="campo-livre">Link da cifra (Cifra Club) — opcional<input class="input" id="imp-url" placeholder="https://www.cifraclub.com.br/artista/musica/"></label>`}
    <div class="campos-2"><label class="campo-livre">Título<input class="input" id="imp-titulo" value="${esc(titulo)}"></label>
      <label class="campo-livre">Autor / intérprete<input class="input" id="imp-artista" value="${esc(artista)}"></label></div>
    <label class="campo-livre">Cifra ou letra<textarea class="input" id="imp-texto" rows="10" spellcheck="false" wrap="off" placeholder="Cole aqui a cifra (acordes em cima da letra), a letra ou um arquivo ChordPro"></textarea></label>
    <div class="acts"><button class="btn ghost" data-no>Cancelar</button><button class="btn primary" data-ok>${icon('check', 16)} ${paraEditor ? 'Usar no editor' : 'Abrir'}</button></div>`,
  (dlg, done) => {
    const txt = $('#imp-texto', dlg);
    $('[data-colar]', dlg).onclick = async () => {
      try { txt.value = await navigator.clipboard.readText(); if (!txt.value.trim()) toast('A área de transferência está vazia'); } catch { toast('Toque no campo e cole (segure o dedo → Colar)'); txt.focus(); }
    };
    $('[data-no]', dlg).onclick = () => done(null);
    $('[data-ok]', dlg).onclick = async () => {
      const dados = { titulo: $('#imp-titulo', dlg).value.trim(), artista: $('#imp-artista', dlg).value.trim(), url: url || $('#imp-url', dlg)?.value.trim() || '' };
      if (!txt.value.trim()) {
        if (dados.url && ehCifraClub(dados.url)) {
          const b = $('[data-ok]', dlg);
          b.innerHTML = '<span class="spin"></span> Abrindo…';
          try { const c = await getCifraClub(dados.url); done({ content: c.chordpro, source: dados.url }); return; } catch { b.innerHTML = `${icon('check', 16)} Abrir`; toast('O Cifra Club não deixou abrir: copie a cifra no site e cole aqui'); }
        } else toast('Cole a cifra ou a letra');
        txt.focus();
        return;
      }
      done({ content: textoParaChordPro(txt.value, dados), source: dados.url });
    };
  }).then((r) => {
    if (!r) return null;
    if (paraEditor) return paraEditor(r);
    abrirPrevia(r.content, r.source || '', back);
    return r;
  });
}

// Busca de músicas: junta os resultados do Cifra Club e do Letras numa lista só (a mesma música aparece
// uma vez, com o link da cifra e o da letra)
async function buscarMusicas(termo) {
  // Uma fonte instável não pode segurar a lista inteira: as duas continuam em paralelo, com prazo máximo.
  const limitar = (p, ms) => Promise.race([p, new Promise((ok) => setTimeout(() => ok(null), ms))]);
  const [cc, lt] = await Promise.all([limitar(buscarCifraClub(termo).catch(() => null), 4500), limitar(buscarLetras(termo).catch(() => null), 4500)]);
  if (!cc && !lt) throw new Error('As buscas não responderam agora');
  const lista = [];
  const chave = (r) => normalizar(tituloLimpo(r.titulo)) + '|' + normalizar(r.artista || '');
  const por = new Map();
  for (const r of cc || []) { const k = chave(r); if (!por.has(k)) { const m = { titulo: r.titulo, artista: r.artista, capa: r.capa, cifra: r.url }; por.set(k, m); lista.push(m); } }
  for (const r of lt || []) {
    const k = chave(r);
    const m = por.get(k) || [...por.values()].find((x) => mesmoNome(tituloLimpo(x.titulo), tituloLimpo(r.titulo)) && mesmoNome(x.artista, r.artista));
    if (m) { m.letra = m.letra || r; m.capa = m.capa || r.capa; continue; }
    const novo = { titulo: r.titulo, artista: r.artista, capa: r.capa, letra: r };
    por.set(k, novo);
    lista.push(novo);
  }
  return lista;
}

// Resultado único da busca: junta os vídeos do YouTube às músicas. O vídeo cujo título tem o nome da música e o
// artista (no título ou no canal) passa a ser o vídeo dela (abre já com cifra, letra e vídeo; o primeiro achado vale);
// os vídeos que não são de nenhuma música da lista entram nela também (ao abrir, o app descobre a música e traz a cifra e a letra)
// (o artista também vale entre parênteses: "정국 (Jung Kook) 'Standing Next to You' Official MV", no canal HYBE LABELS,
// só tem o nome dele ali. Antes os parênteses saíam antes de procurar o artista, e o clipe oficial não era reconhecido)
const quemNoVideo = (v) => ` ${normalizar(`${v.titulo || ''} ${v.canal || ''}`)} `;
// O clipe oficial antes dos outros vídeos da mesma música: o "Official MV" e o "clipe oficial" sobem; o de letra, ao
// vivo, a coreografia, o karaokê, o cover, o remix… descem (a não ser que a palavra seja do próprio título da música)
const VIDEO_OFICIAL = /\b(official\s+(music\s+)?video|official\s+mv|mv|m\s*v|music\s+video|videoclipe|clipe\s+oficial|video\s+oficial|clipe)\b/;
const VIDEO_OUTRO = /\b(lyrics?|letra|legendad[oa]|traducao|translation|sub\s+esp|karaoke|cover|reaction|react|dance\s+practice|choreography|coreografia|fancam|live|ao\s+vivo|performance|remix|instrumental|piano|8d|slowed|sped\s+up|nightcore|tutorial|aula|cifra|how\s+to\s+play|visualizer|teaser|behind|making)\b/;
function notaDoVideo(v, titulo = '') {
  const t = normalizar(v.titulo || '');
  const daMusica = ` ${normalizar(titulo)} `;
  const tem = (re) => { const m = re.exec(t); return Boolean(m) && !daMusica.includes(` ${m[0]} `); };
  return (tem(VIDEO_OFICIAL) ? 3 : 0) - (tem(VIDEO_OUTRO) ? 3 : 0) + (/\bvevo\b/.test(normalizar(v.canal || '')) ? 1 : 0);
}
// os vídeos na ordem de preferência para a música: o clipe oficial primeiro; empatados, na ordem da busca
const videosPorPreferencia = (videos, titulo = '') => (videos || []).map((v, i) => ({ v, i, n: notaDoVideo(v, titulo) }))
  .sort((a, b) => b.n - a.n || a.i - b.i).map((x) => x.v);
// da busca do YouTube pelo título e o artista: o melhor entre os que têm o título da música (sem nenhum com o título,
// a ordem da busca)
function videosDaMusica(videos, titulo, artista = '') {
  const t = normalizar(tituloLimpo(titulo));
  const comTitulo = (videos || []).filter((v) => t && ` ${normalizar(tituloCruDoVideo(v.titulo))} `.includes(` ${t} `));
  const doArtista = comTitulo.filter((v) => artistasDe('', artista).some((a) => artistaNoTexto(a, quemNoVideo(v))));
  const melhores = videosPorPreferencia(doArtista.length ? doArtista : comTitulo, titulo);
  return melhores.length ? [...melhores, ...(videos || []).filter((v) => !melhores.includes(v))] : (videos || []);
}
function juntarVideos(musicas, videos) {
  const tit = (m) => normalizar(tituloLimpo(m.titulo));
  const lista = musicas.map((m) => ({ ...m }));
  const porTamanho = [...lista].sort((a, b) => tit(b).length - tit(a).length);
  const sobra = [];
  for (const v of videos) {
    const cru = tituloCruDoVideo(v.titulo);
    const noTitulo = ` ${normalizar(cru)} `;
    const quem = quemNoVideo(v);
    const m = porTamanho.find((x) => tit(x).length >= 2 && noTitulo.includes(` ${tit(x)} `)
      && artistasDe('', x.artista).some((a) => artistaNoTexto(a, quem)));
    // outro vídeo da mesma música (ao vivo, letra, outra versão) não se repete na lista; fica o clipe oficial (antes
    // ficava o primeiro achado, que podia ser o de letra)
    if (m) { if (!m.video || notaDoVideo(v, m.titulo) > notaDoVideo(m.video, m.titulo)) m.video = v; } else sobra.push(v);
  }
  return [...lista, ...sobra.map((v) => ({ titulo: tituloDoVideo(v.titulo) || v.titulo, artista: v.canal || '', capa: v.capa, video: v }))];
}
// cifra, letra e vídeo de um resultado da busca, já juntos
const buscarTudo = (termo, nMusicas = 8, nVideos = 6) => {
  const pVideos = buscarYoutube(termo).catch(() => []);
  return buscarMusicas(termo).catch(async (e) => { if ((await noMaximo(pVideos, 2200, [])).length) return []; throw e; })
    .then(async (ms) => juntarVideos(ms.slice(0, nMusicas), (await noMaximo(pVideos, 2200, [])).slice(0, nVideos)));
};
// artista (Cifra Club): foto redonda; abre a página dele com as músicas mais tocadas
// (a foto já é a definitiva: a preparada antes de desenhar (prepararFotosArtistas) ou a última guardada. A do Cifra Club
// não aparece primeiro: ela era a foto antiga, e em milissegundos piscava para a nova)
const tileArtista = (a) => {
  const foto = a.fotoFinal !== undefined ? a.fotoFinal : fotoConhecida(a.nome);
  return `<a class="tile tile-artista" href="#/artista/${encodeURIComponent(a.slug)}/${encodeURIComponent(a.nome)}">
  <div class="cover" data-artista-foto data-nome="${esc(a.nome)}" data-slug="${esc(a.slug)}"${foto ? ` data-mostrando="${esc(foto)}"` : ''}>${foto ? `<img src="${esc(foto)}" alt="" referrerpolicy="no-referrer" loading="lazy">` : icon('mic', 40)}</div><b>${esc(a.nome)}</b><small>Artista</small></a>`;
};
// O artista certo numa busca do Cifra Club: primeiro o de nome igual (a busca por "Justice" traz a "Victoria Justice"
// antes do Justice). Um nome dentro do outro só vale quando a diferença é um título ("Gilson" e "Frei Gilson") ou
// quando o nome tem mais de uma palavra ("Marcelo Rossi" e "Padre Marcelo Rossi"); uma palavra só ("Justice") dentro
// do nome de outra pessoa não é ela
const TITULO_NO_NOME = /^(padre|pe|frei|fr|irmao|irma|ir|dom|diacono|monsenhor|mons|cardeal|ministerio|comunidade)$/;
function mesmoArtista(a, b) {
  const A = normalizar(nomeReligioso(a));
  const B = normalizar(nomeReligioso(b));
  if (!A || !B) return false;
  if (A === B) return true;
  const [curto, longo] = A.length <= B.length ? [A, B] : [B, A];
  if (!` ${longo} `.includes(` ${curto} `)) return false;
  const resto = ` ${longo} `.replace(` ${curto} `, ' ').trim().split(' ');
  return curto.includes(' ') || resto.every((p) => TITULO_NO_NOME.test(p));
}
const artistaCerto = (lista, nome) => lista.find((a) => normalizar(nomeReligioso(a.nome)) === normalizar(nomeReligioso(nome)))
  || lista.find((a) => mesmoArtista(a.nome, nome)) || null;
// ---- uma dupla é um artista só (lib/artistas.js): "Jorge & Mateus" não vira "Jorge" (que vinha como o Jorge Ben) e
// "Mateus". O Deezer diz se o nome inteiro é de um artista conhecido; a resposta fica guardada no aparelho e, quando
// muda o que se sabia (era "Anitta & Ludmilla", duas artistas), o que está na tela é desenhado de novo
const CHAVE_UNICOS = 'songbook.artistasUnicos';
let artistasUnicos = null;
const unicosGuardados = () => {
  if (!artistasUnicos) { try { artistasUnicos = JSON.parse(localStorage.getItem(CHAVE_UNICOS) || '{}') || {}; } catch { artistasUnicos = {}; } }
  return artistasUnicos;
};
const artistaUnico = (nome) => unicosGuardados()[normalizar(nome)];
const conferindoUnicos = new Map();
function conferirArtistaUnico(nome) {
  const k = normalizar(nome);
  if (!k || k in unicosGuardados()) return Promise.resolve(unicosGuardados()[k]);
  if (!conferindoUnicos.has(k)) {
    conferindoUnicos.set(k, jsonp(`https://api.deezer.com/search/artist?q=${encodeURIComponent(nome)}&limit=5`).then((r) => {
      if (!Array.isArray(r?.data)) return undefined;
      const um = r.data.some((a) => normalizar(a.name) === k && (a.nb_fan || 0) >= 1000);
      unicosGuardados()[k] = um;
      try { localStorage.setItem(CHAVE_UNICOS, JSON.stringify(unicosGuardados())); } catch { /* sem espaço: fica na sessão */ }
      // (só avisa quando o palpite de antes estava errado: a dupla presumida era de duas pessoas, ou o contrário)
      const palpite = separarArtistas(nome).length === 1;
      if (palpite !== um) dispatchEvent(new CustomEvent('songbook:artista-unico', { detail: { nome } }));
      return um;
    }).catch(() => undefined));
  }
  return conferindoUnicos.get(k);
}
// os artistas do texto, sem separar as duplas (e já pergunta ao Deezer pelos nomes que ainda não conhece)
function artistasDoNome(texto, { comE = false } = {}) {
  for (const n of nomesParaConferir(texto, { comE })) if (artistaUnico(n) === undefined && navigator.onLine) void conferirArtistaUnico(n);
  return separarArtistas(texto, { unico: artistaUnico, comE });
}
const primeiroArtistaDe = (texto) => {
  for (const n of nomesParaConferir(texto, { comE: true })) if (artistaUnico(n) === undefined && navigator.onLine) void conferirArtistaUnico(n);
  return primeiroArtista(texto, { unico: artistaUnico });
};
// as pessoas dos créditos, cada uma com os papéis dela: o artista principal, quem participa (o "feat." do nome do
// artista ou do título: "Lady Gaga feat. Bruno Mars", "Die With A Smile (part. Bruno Mars)"), a composição e a letra
const FEAT = /\s*(?:\(|\[|-\s)?\s*\b(?:feat\.?|ft\.?|featuring|part\.?|participa[çc][ãa]o(?: especial)?(?: de)?|com|with)\s+/i;
function pessoasDosCreditos({ artista = '', titulo = '', compositor = '', letrista = '' } = {}) {

  const [principal, ...feats] = String(artista || '').split(FEAT);
  const doTitulo = /[([]\s*(?:feat\.?|ft\.?|featuring|part\.?|participa[çc][ãa]o(?: especial)?(?: de)?|com|with)\s+([^)\]]+)[)\]]/i.exec(titulo || '')?.[1] || '';
  const pessoas = [];
  const juntar = (nome, papel) => {
    const ja = pessoas.find((x) => normalizar(x.nome) === normalizar(nome));
    if (ja) { if (!ja.papeis.includes(papel)) ja.papeis.push(papel); } else pessoas.push({ nome, papeis: [papel] });
  };
  // artistas e participações: separados por vírgula, "/" ou " x "; o "&" separa só quem não é uma dupla ("Jorge &
  // Mateus" e "Zezé Di Camargo e Luciano" ficam juntos: veja artistasDoNome)
  artistasDoNome(principal).forEach((n) => juntar(n, 'Artista principal'));
  [...feats, doTitulo].flatMap((f) => artistasDoNome(f)).forEach((n) => juntar(n, 'Participação'));
  // compositores: também separados por " e " (a dupla de compositores conhecida como um nome só fica junta)
  artistasDoNome(compositor, { comE: true }).forEach((n) => juntar(n, 'Composição'));
  artistasDoNome(letrista, { comE: true }).forEach((n) => juntar(n, 'Letra'));
  return pessoas;
}
// ---- créditos como o SongDNA do Spotify: as pessoas da música em bolinhas, com a foto de cada uma (ou as iniciais
// numa cor dela), e o "Explorar", que abre todas elas em detalhe
const corDaPessoa = (n) => `hsl(${[...n].reduce((h, c) => (h * 31 + c.charCodeAt(0)) % 360, 7)} 45% 38%)`;
const papeisCurtos = (p) => p.papeis[0] + (p.papeis.length > 1 ? ` + ${p.papeis.length - 1}` : '');
// (sem foto: a pessoa com a nota musical, como no Spotify, no lugar das iniciais)
// a foto, se for foto mesmo ('' para a imagem que o site põe no lugar da que não tem)
const fotoReal = (url) => (url && typeof url === 'string' && !ehImagemPadrao(url) ? url : '');
const semFotoArtista = (size = 48) => `<span class="sem-foto-artista">${icon('artistaSemFoto', size)}</span>`;
const avatarDe = (p, i, classe = 'ref-avatar') => `<span class="${classe} sem-foto" data-foto="${i}">${semFotoArtista()}</span>`;
// a foto de cada pessoa nas bolinhas [data-foto] da caixa (as que não têm foto ficam com as iniciais)
// ---- as músicas da missa (o acervo litúrgico, o Hinário e os textos da CNBB, a Cindy Ferrarezi, o Músicas para Missa)
// O artista delas costuma ser um compositor ou um padre pouco conhecido, e a foto e a apresentação procuradas só pelo
// nome achavam um xará famoso ("José Alves", de "Salve Rainha", vinha com a foto e a história de um cantor de funk). Nelas,
// a foto e a apresentação só vêm de quem é com certeza do meio católico: o nome com o título religioso (Padre, Frei,
// Irmã, Dom, Ministério, Comunidade…), procurado com o título por extenso ("Pe. Zezinho" → "Padre Zezinho"), e os
// artistas católicos que o app já conhece. Os outros ficam com o desenho do app (a pessoa com a nota)
const ehDaLiturgia = (x) => {
  const s = typeof x === 'string' ? x : [x?.source, x?.fonte, x?.cifra, x?.url].find((v) => typeof v === 'string' && v) || '';
  return /^(acervo|hinario|cnbb):/.test(s) || /cindyferrarezi\.com|musicasparamissa\.com/.test(s) || ['acervo', 'hinario', 'cnbb', 'mpm', 'cindy'].includes(x?.fonte);
};
const TITULO_RELIGIOSO = /^(padre|pe\.?|frei|fr\.|irm[ãa]o?|ir\.|dom|di[áa]cono|monsenhor|mons\.|cardeal|minist[ée]rio|comunidade)\s+\S/i;
const nomeReligioso = (n) => String(n || '').trim().replace(/^pe\.?\s+/i, 'Padre ').replace(/^fr\.\s+/i, 'Frei ').replace(/^mons\.\s+/i, 'Monsenhor ');
// (além dos católicos mais ouvidos da Busca, autores de cantos de missa conhecidos sem título religioso)
const AUTORES_CATOLICOS = ['Cindy Ferrarezi', 'Ziza Fernandes', 'Adriana Arydes', 'Eugênio Jorge'];
const confiavelNaLiturgia = (n) => Boolean(String(n || '').trim()) && (TITULO_RELIGIOSO.test(String(n).trim())
  || [...ARTISTAS_CATOLICOS, ...AUTORES_CATOLICOS].some((a) => normalizar(a) === normalizar(n) || normalizar(a) === normalizar(nomeReligioso(n))));
// a foto de uma pessoa da música: na música da missa, só de quem é confiável (veja acima); '' para ficar o desenho
function fotoDaPessoa(nome, { liturgia = false, slug = '', titulo = '' } = {}) {
  if (!liturgia) return fotoDoArtista(nome, slug, titulo);
  return confiavelNaLiturgia(nome) ? fotoDoArtista(nomeReligioso(nome), slug, titulo) : Promise.resolve('');
}
// A foto de quem só compôs ou produziu (não canta na música): só a de um lugar que é com certeza dele — o canal
// verificado do YouTube ou a página de músico na Wikipédia. O Deezer e a busca por nome traziam um xará (o "Henry
