        const classe = (p) => (p ? (((p.FundamentalNote + (p.AccidentalHalfTones || 0)) % 12) + 12) % 12 : null);
        if (c.RootPitch) acordes.push({ t, raiz: classe(c.RootPitch), tipo: c.ChordKind, baixo: classe(c.BassPitch) });
